// THE BRIEF — every capability in this feature, folded into ONE ranked list of what to do.
//
// Twenty-five modules each produce their own answer and nothing composed them, so anything asked to
// "use the finance system" had to re-derive the same synthesis every time. This is that synthesis,
// once, as data.
//
// IT COMPOSES, IT DOES NOT RECOMPUTE. Every input is another capability's OUTPUT. Nothing here
// recalculates a runway or re-prices a transfer, because a second implementation of a number is a
// second answer to the same question, and the two will disagree eventually.
//
// TWO TIERS, BECAUSE ONE ORDERING CANNOT HOLD BOTH.
//
//   DO NOT MISS — things with a date. A minimum payment due Friday is not comparable to a $5,000
//     opportunity by any rate; it is comparable to a late fee and a credit event. Sorted by WHEN.
//   BEST RETURN — everything else, sorted by what it is worth PER HOUR OF YOUR EFFORT. A $40 fee
//     waiver that takes a ten-minute phone call beats a $5,000 grant that takes eighty hours, and
//     ranking by size alone gets that exactly backwards.
//
// ABSENT IS NOT ZERO, and this is the discipline that makes the brief trustworthy. A capability that
// was never run contributes NOTHING and is NAMED as missing. A brief reporting "$0 available in fee
// waivers" when the fee audit never ran is a lie, and it is the specific lie that would make somebody
// stop looking.
import { type Money, money, scale } from "@/features/finance/lib/money";
import type { Position } from "@/features/finance/lib/position";
import { type Runway, survivesHorizon } from "@/features/finance/lib/runway";
import type { ViableIncome } from "@/features/finance/lib/viable";
import type { Priority } from "@/features/finance/lib/priority";
import type { NegotiationCase } from "@/features/finance/lib/negotiate";
import type { TransferAssessment } from "@/features/finance/lib/transfer";
import type { Assessment } from "@/features/finance/lib/opportunity";
import { type ObligationCalendar, dueBetween } from "@/features/finance/lib/obligations";

export type Tier = "do-not-miss" | "best-return" | "blocked";

export interface Action {
  readonly id: string;
  readonly title: string;
  /** Which capability produced it, so a figure can be traced back and checked. */
  readonly source: string;
  readonly tier: Tier;
  /** `YYYY-MM-DD`, for anything with a date. */
  readonly by?: string;
  readonly worth?: Money;
  /** What the worth MEANS — a year of interest, a one-off, an expectation. Without this the number
   *  is not comparable to the one under it. */
  readonly worthBasis?: string;
  readonly effortHours?: number;
  /** worth ÷ effort. UNDEFINED when either is, and it sorts last rather than as zero. */
  readonly perHour?: Money;
  readonly why: string;
  /** True when this rests on something incomplete or unchecked. */
  readonly provisional: boolean;
  readonly blockedBy?: string;
}

export interface Brief {
  readonly asOf: string;
  readonly currency: string;
  /** Where you stand, in one sentence. */
  readonly headline: string;
  readonly doNotMiss: readonly Action[];
  readonly bestReturn: readonly Action[];
  readonly blocked: readonly Action[];
  /** Capabilities that produced nothing, BY NAME — the difference between "nothing to do" and
   *  "nothing looked". */
  readonly absent: readonly string[];
  /** What every figure above is standing on. */
  readonly caveats: readonly string[];
}

export interface BriefInput {
  /** `YYYY-MM-DD`. Passed in, never a clock. */
  readonly asOf: string;
  readonly currency: string;
  readonly position?: Position;
  readonly runway?: Runway;
  readonly viable?: ViableIncome;
  readonly priority?: Priority;
  readonly negotiation?: readonly NegotiationCase[];
  readonly transfers?: readonly TransferAssessment[];
  readonly opportunities?: readonly Assessment[];
  readonly calendar?: ObligationCalendar;
  /** How far ahead a dated obligation counts as urgent. */
  readonly horizonDays?: number;
  /** Effort defaults, NAMED rather than buried, because they drive the whole ranking. */
  readonly callHours?: number;
  readonly transferHours?: number;
}

const addDays = (iso: string, n: number): string =>
  new Date(Date.parse(`${iso}T00:00:00Z`) + n * 86_400_000).toISOString().slice(0, 10);

/** worth ÷ effort, or undefined — never zero, which would sort a priceless thing among the worthless. */
function perHourOf(worth: Money | undefined, hours: number | undefined, currency: string): Money | undefined {
  if (!worth || hours === undefined || hours <= 0) return undefined;
  return money(Math.round(worth.minor / hours), currency);
}

export function buildBrief(input: BriefInput): Brief {
  const {
    asOf,
    currency,
    position,
    runway,
    viable,
    priority,
    negotiation,
    transfers,
    opportunities,
    calendar,
    horizonDays = 30,
    callHours = 0.5,
    transferHours = 1,
  } = input;

  const actions: Action[] = [];
  const absent: string[] = [];
  const caveats: string[] = [];

  // PROVISIONAL propagates from the bottom. Everything derived from an incomplete position or an
  // unverified ledger is itself provisional, and saying so once at the top is not enough — the
  // reader acts on individual lines.
  const unverified = position?.provenance.startsWith("UNVERIFIED") ?? false;
  const provisional = !position || position.complete === false || unverified;
  if (unverified) caveats.push(`the ledger under this was never reconciled: ${position?.provenance}`);
  if (position && !position.complete) {
    caveats.push(`the position is incomplete — ${position.problems.length} unresolved issue(s), so every figure below inherits them`);
  }

  // ── DO NOT MISS ────────────────────────────────────────────────────────────────────────────────
  if (calendar) {
    for (const o of dueBetween(calendar, asOf, addDays(asOf, horizonDays))) {
      actions.push({
        id: `due:${o.account}:${o.date}:${o.label}`,
        title: `${o.label} — ${o.amount.minor} due`,
        source: "obligations",
        tier: "do-not-miss",
        by: o.date,
        worth: o.amount,
        worthBasis: "the amount due",
        // The assumed-date note applies to a MINIMUM too, and especially to one: `obligations` places
        // an unknown due day on the 1st — the earliest it could plausibly fall — so the date is the
        // conservative guess rather than a fact, and the one obligation that must not be late is the
        // one where that distinction matters most.
        why:
          (o.kind === "minimum"
            ? "a missed minimum is a late fee, a penalty rate on the whole balance, and a credit event that outlasts the month"
            : "a standing obligation") +
          (o.confidence === "assumed" ? " — the DATE is assumed, not observed" : ""),
        provisional: provisional || o.confidence === "assumed",
      });
    }
  } else absent.push("obligations — no calendar was built, so nothing here knows what is due");

  // ── BEST RETURN ────────────────────────────────────────────────────────────────────────────────
  if (negotiation) {
    // A hardship case is NOT a best-return item and is handled below as dated work — it has to
    // happen before a missed payment, and ranking it by expectation per hour would bury it.
    for (const c of negotiation.filter((x) => x.ask !== "hardship-plan")) {
      // The highest-return action available to most people, and the one nobody takes: a phone call
      // that costs nothing and cannot lower a credit score.
      const worth = c.annualValueIfWon;
      actions.push({
        id: `call:${c.account}:${c.ask}`,
        title: `${c.institution} — ask for a ${c.ask.replace(/-/g, " ")}`,
        source: "negotiate",
        tier: "best-return",
        worth,
        worthBasis: c.ask === "fee-waiver" ? "the fee, one-off" : "a year, if granted",
        effortHours: callHours,
        perHour: perHourOf(worth, callHours, currency),
        why: c.why,
        provisional,
      });
    }
  } else absent.push("negotiate — no call list was prepared");

  if (transfers) {
    for (const t of transfers.filter((x) => x.worthIt)) {
      actions.push({
        id: `transfer:${t.sourceAccount}:${t.offerId}`,
        title: `move ${t.moved.minor} from ${t.sourceAccount} to ${t.institution}`,
        source: "transfer",
        tier: "best-return",
        worth: t.netBenefit,
        worthBasis: "interest avoided over the promotion, less the fee",
        effortHours: transferHours,
        perHour: perHourOf(t.netBenefit, transferHours, currency),
        why: `${t.interestAvoided.minor} of interest avoided against a ${t.fee.minor} fee — and the balance must be gone before the promotion ends`,
        provisional,
      });
    }
    if (!transfers.some((x) => x.worthIt) && transfers.length) {
      caveats.push(`${transfers.length} transfer offer(s) were priced and NONE beat its fee — that is a result, not a gap`);
    }
  } else absent.push("transfer — no offers were priced");

  if (opportunities) {
    for (const a of opportunities.filter((x) => x.verdict === "biddable" && x.beatsContracting)) {
      actions.push({
        id: `bid:${a.opportunity.id}`,
        title: `bid: ${a.opportunity.title}`,
        source: "opportunity",
        tier: "best-return",
        by: a.opportunity.closes,
        worth: a.expected,
        worthBasis: "expectation — award × hit rate, not revenue",
        effortHours: a.opportunity.bidHours,
        perHour: a.perHour,
        why: `beats billing the same ${a.opportunity.bidHours}h`,
        provisional,
      });
    }
  } else absent.push("opportunity — no funding sources were scanned");

  if (priority?.target && priority.toDebt.minor > 0) {
    actions.push({
      id: `pay:${priority.target.account}`,
      title: `put ${priority.toDebt.minor} above the minimum into ${priority.target.institution}`,
      source: "priority",
      tier: "best-return",
      worth: scale(priority.toDebt, 1),
      worthBasis: "the payment itself — the return is the rate it stops accruing",
      why: priority.target.why,
      provisional,
    });
  }
  if (priority?.toBuffer.minor) {
    actions.push({
      id: "buffer",
      title: `put ${priority.toBuffer.minor} into the emergency buffer`,
      source: "priority",
      tier: "best-return",
      worth: priority.toBuffer,
      worthBasis: "the amount set aside",
      why: "a buffer beats the rate until it exists — without one the next unplanned bill goes back onto the highest-rate card",
      provisional,
    });
  }
  if (!priority) absent.push("priority — nothing decided where this month's spare money goes");

  // ── BLOCKED ────────────────────────────────────────────────────────────────────────────────────
  if (negotiation) {
    for (const c of negotiation.filter((x) => x.ask === "hardship-plan")) {
      // Not blocked in the sense of impossible — blocked in the sense that it must happen BEFORE
      // something else, and the something else is a missed payment.
      actions.push({
        id: `hardship:${c.account}`,
        title: `${c.institution} — hardship arrangement, BEFORE a payment is missed`,
        source: "negotiate",
        tier: "do-not-miss",
        worth: c.annualValueIfWon,
        worthBasis: "a year, if granted",
        effortHours: callHours,
        perHour: perHourOf(c.annualValueIfWon, callHours, currency),
        why: c.urgency ?? c.why,
        provisional,
      });
    }
  }
  if (opportunities) {
    for (const a of opportunities.filter((x) => x.verdict === "ineligible" && x.unmet.length)) {
      actions.push({
        id: `unblock:${a.opportunity.id}`,
        title: `cannot bid ${a.opportunity.title}`,
        source: "opportunity",
        tier: "blocked",
        why: a.why ?? "ineligible",
        blockedBy: a.unmet.join(", "),
        provisional,
      });
    }
  }

  const byDate = (a: Action, b: Action): number => (a.by ?? "9999").localeCompare(b.by ?? "9999");
  const byReturn = (a: Action, b: Action): number =>
    (b.perHour?.minor ?? -1) - (a.perHour?.minor ?? -1) ||
    (b.worth?.minor ?? -1) - (a.worth?.minor ?? -1) ||
    a.title.localeCompare(b.title);

  return {
    asOf,
    currency,
    headline: headlineFor(input, provisional),
    doNotMiss: actions.filter((a) => a.tier === "do-not-miss").sort(byDate),
    bestReturn: actions.filter((a) => a.tier === "best-return").sort(byReturn),
    blocked: actions.filter((a) => a.tier === "blocked"),
    absent,
    caveats,
  };
}

/**
 * Where you stand, in one sentence.
 *
 * The runway on the LOW band is the sentence when there is one, because it is the fact every other
 * decision bends around. With no runway it says so rather than reaching for a cheerier number.
 */
export function headlineFor(input: BriefInput, provisional: boolean): string {
  const { runway, viable, position } = input;
  const mark = provisional ? " (PROVISIONAL — see the caveats)" : "";

  if (runway?.headline.months.length) {
    const h = runway.headline;
    if (!survivesHorizon(h)) {
      return `the money runs out in ${h.exhaustsIn} on the LOW income band — ${h.monthsOfCover} whole month(s) of cover, and ${h.monthlyGap.minor} more per month would close it${mark}`;
    }
    return `on the LOW income band the money holds through ${runway.through}, tightest at ${h.tightest!.month}${mark}`;
  }
  if (viable?.headline) {
    return `${viable.headline.worstMonth.minor} a month keeps everything current, measured on ${viable.headline.worstMonthName} — the worst month, not the average${mark}`;
  }
  if (position) {
    return `net worth ${position.netWorth.minor}, ${position.liquid.minor} liquid, ${position.totalDebt.minor} owed as of ${position.asOf}${mark}`;
  }
  return "nothing has been computed yet — ingest a statement and the rest follows";
}

/** Everything the best-return list is worth if all of it lands. Contingent by construction. */
export const totalIfEverythingLands = (b: Brief): Money =>
  money(b.bestReturn.reduce((n, a) => n + (a.worth?.minor ?? 0), 0), b.currency);

/** Hours the best-return list actually asks for — the constraint people find out about late. */
export const totalEffortHours = (b: Brief): number =>
  b.bestReturn.reduce((n, a) => n + (a.effortHours ?? 0), 0);

/** The one thing to do next, or nothing. Dated work first, exactly as the tiers say. */
export const nextAction = (b: Brief): Action | undefined => b.doNotMiss[0] ?? b.bestReturn[0];

