import { describe, it, expect } from "vitest";
import { fromMajor, type Money } from "@/features/finance/lib/money";
import type { Position } from "@/features/finance/lib/position";
import type { Runway, RunwayResult } from "@/features/finance/lib/runway";
import type { NegotiationCase } from "@/features/finance/lib/negotiate";
import type { TransferAssessment } from "@/features/finance/lib/transfer";
import type { Assessment } from "@/features/finance/lib/opportunity";
import type { ObligationCalendar } from "@/features/finance/lib/obligations";
import type { Priority } from "@/features/finance/lib/priority";
import {
  type BriefInput,
  buildBrief,
  nextAction,
  totalEffortHours,
  totalIfEverythingLands,
} from "@/features/finance/lib/brief";

// SYNTHETIC FIXTURES ONLY. No real balance, statement or offer belongs in this repo.
const usd = (major: number): Money => fromMajor(major, "USD");

const position = (over: Partial<Position> = {}): Position => ({
  asOf: "2026-07-01",
  currency: "USD",
  accounts: [],
  netWorth: usd(-800),
  liquid: usd(1200),
  totalDebt: usd(2000),
  dailyInterest: usd(1),
  minimumsDue: usd(75),
  complete: true,
  problems: [],
  provenance: "reconciled · synthetic",
  ...over,
});

const result = (over: Partial<RunwayResult> = {}): RunwayResult => ({
  scenario: "low",
  months: [
    { month: "2026-08", opening: usd(1200), income: usd(2000), obligations: usd(2500), discretionary: usd(600), net: usd(-1100), closing: usd(100) },
    { month: "2026-09", opening: usd(100), income: usd(2000), obligations: usd(2500), discretionary: usd(600), net: usd(-1100), closing: usd(-1000), shortfall: usd(1000) },
  ],
  exhaustsIn: "2026-09",
  monthsOfCover: 1,
  tightest: { month: "2026-09", opening: usd(100), income: usd(2000), obligations: usd(2500), discretionary: usd(600), net: usd(-1100), closing: usd(-1000), shortfall: usd(1000) },
  monthlyGap: usd(550),
  ...over,
});

const runway = (r: RunwayResult = result()): Runway => ({
  asOf: "2026-07-01",
  currency: "USD",
  startingLiquid: usd(1200),
  low: r,
  expected: r,
  high: r,
  headline: r,
  through: "2026-09",
  problems: [],
  provenance: "reconciled · synthetic",
});

const negotiationCase = (over: Partial<NegotiationCase> = {}): NegotiationCase => ({
  account: "a",
  institution: "Alpha Card",
  ask: "fee-waiver",
  why: "a fee landed recently and a first-offence waiver is close to routine",
  evidence: [],
  doNotSay: [],
  realistic: "one fee waived is the usual outcome",
  annualValueIfWon: usd(39),
  ...over,
});

const transfer = (over: Partial<TransferAssessment> = {}): TransferAssessment => ({
  offerId: "omega",
  institution: "Omega Bank",
  sourceAccount: "a",
  moved: usd(5000),
  fee: usd(150),
  openingBalance: usd(5150),
  interestWithout: usd(900),
  interestWith: usd(0),
  interestAvoided: usd(900),
  netBenefit: usd(750),
  worthIt: true,
  balanceAtPromoEnd: usd(0),
  costOfNotFinishing: usd(0),
  requiredMonthly: usd(287),
  warnings: [],
  ...over,
});

const calendar = (): ObligationCalendar => ({
  from: "2026-07-01",
  to: "2026-12-31",
  obligations: [
    { date: "2026-07-03", label: "Alpha Card minimum", account: "a", amount: usd(90), kind: "minimum", confidence: "observed" },
    { date: "2026-07-20", label: "RENT", account: "checking", amount: usd(1500), kind: "recurring", confidence: "observed" },
  ],
  byMonth: [],
  notes: [],
});

const input = (over: Partial<BriefInput> = {}): BriefInput => ({
  asOf: "2026-07-01",
  currency: "USD",
  ...over,
});

describe("TWO TIERS, because one ordering cannot hold both", () => {
  it("puts dated work above return, however much the return is worth", () => {
    // A $90 minimum due Friday is not comparable to a $750 transfer by any rate — it is comparable
    // to a late fee and a credit event.
    const b = buildBrief(input({ calendar: calendar(), transfers: [transfer()], position: position() }));
    expect(b.doNotMiss.map((a) => a.by)).toEqual(["2026-07-03", "2026-07-20"]);
    expect(nextAction(b)!.title).toContain("Alpha Card minimum");
    expect(b.bestReturn[0].title).toContain("move 500000");
  });

  it("sorts dated work by WHEN, not by size", () => {
    const b = buildBrief(input({ calendar: calendar() }));
    // Rent is 16x the minimum and comes second, because it is due later.
    expect(b.doNotMiss[0].worth!.minor).toBeLessThan(b.doNotMiss[1].worth!.minor);
  });

  it("sorts return by value PER HOUR, not by value", () => {
    // A $39 waiver from a half-hour call is $78/h. A $750 transfer taking an hour is $750/h. But a
    // $39 waiver against a 40-hour bid worth $600 is the one that flips the naive ordering.
    const b = buildBrief(
      input({
        negotiation: [negotiationCase()],
        opportunities: [
          {
            opportunity: { id: "g", title: "Grant", sourceId: "sbir", vehicle: "sbir", award: usd(6000), closes: "2026-09-01", bidHours: 40, hitRate: 0.1, requires: [] },
            verdict: "biddable",
            expected: usd(600),
            perHour: usd(15),
            contractingAlternative: usd(4800),
            beatsContracting: true,
            hoursAvailable: 100,
            unmet: [],
          } as Assessment,
        ],
      }),
    );
    // The grant is worth 15x more in total and ranks BELOW the phone call.
    expect(b.bestReturn.map((a) => a.source)).toEqual(["negotiate", "opportunity"]);
    expect(b.bestReturn[0].worth!.minor).toBeLessThan(b.bestReturn[1].worth!.minor);
    expect(b.bestReturn[0].perHour!.minor).toBeGreaterThan(b.bestReturn[1].perHour!.minor);
  });

  it("sorts an action with no per-hour figure LAST rather than as zero", () => {
    const b = buildBrief(
      input({
        negotiation: [negotiationCase()],
        priority: {
          currency: "USD", strategy: "avalanche", available: usd(300), lumpAvailable: usd(0),
          minimums: usd(75), toBuffer: usd(0), toDebt: usd(300),
          allocations: [], target: { account: "a", institution: "Alpha Card", why: "highest rate" },
          order: ["a"], warnings: [],
        } as Priority,
      }),
    );
    // The payment has no effort estimate, so it has no rate and sorts after the priced call.
    expect(b.bestReturn[b.bestReturn.length - 1].source).toBe("priority");
    expect(b.bestReturn[b.bestReturn.length - 1].perHour).toBeUndefined();
  });
});

describe("ABSENT IS NOT ZERO", () => {
  it("names every capability that produced nothing", () => {
    // A brief reporting "$0 available in fee waivers" when the audit never ran is the specific lie
    // that makes somebody stop looking.
    const b = buildBrief(input());
    expect(b.absent.join(" ")).toContain("negotiate");
    expect(b.absent.join(" ")).toContain("transfer");
    expect(b.absent.join(" ")).toContain("opportunity");
    expect(b.absent.join(" ")).toContain("obligations");
    expect(b.absent.join(" ")).toContain("priority");
    expect(b.bestReturn).toEqual([]);
  });

  it("distinguishes 'nothing looked' from 'looked and found nothing'", () => {
    const looked = buildBrief(input({ transfers: [transfer({ worthIt: false, netBenefit: usd(-50) })] }));
    expect(looked.absent.join(" ")).not.toContain("transfer");
    expect(looked.caveats.join(" ")).toContain("NONE beat its fee");
    expect(looked.caveats.join(" ")).toContain("a result, not a gap");
  });

  it("says plainly when nothing has been computed at all", () => {
    expect(buildBrief(input()).headline).toContain("ingest a statement and the rest follows");
  });
});

describe("provisional propagates to every line, not just the top", () => {
  it("marks every action provisional when the ledger was never reconciled", () => {
    const b = buildBrief(
      input({
        position: position({ provenance: "UNVERIFIED — no opening balance · 40 txns" }),
        negotiation: [negotiationCase()],
        calendar: calendar(),
      }),
    );
    expect(b.caveats.join(" ")).toContain("never reconciled");
    expect([...b.doNotMiss, ...b.bestReturn].every((a) => a.provisional)).toBe(true);
    expect(b.headline).toContain("PROVISIONAL");
  });

  it("marks them provisional when the position is incomplete", () => {
    const b = buildBrief(input({ position: position({ complete: false, problems: ["'savings' has no balance"] }), negotiation: [negotiationCase()] }));
    expect(b.caveats.join(" ")).toContain("inherits them");
    expect(b.bestReturn.every((a) => a.provisional)).toBe(true);
  });

  it("does not mark anything provisional when the position is complete and reconciled", () => {
    const b = buildBrief(input({ position: position(), negotiation: [negotiationCase()], calendar: calendar() }));
    expect(b.caveats).toEqual([]);
    expect([...b.doNotMiss, ...b.bestReturn].every((a) => !a.provisional)).toBe(true);
    expect(b.headline).not.toContain("PROVISIONAL");
  });

  it("marks an obligation whose DATE was assumed, even in an otherwise clean brief", () => {
    const c = calendar();
    const assumed: ObligationCalendar = {
      ...c,
      obligations: [{ ...c.obligations[0], confidence: "assumed" }],
    };
    const b = buildBrief(input({ position: position(), calendar: assumed }));
    expect(b.doNotMiss[0].provisional).toBe(true);
    expect(b.doNotMiss[0].why).toContain("DATE is assumed");
  });
});

describe("a hardship case is dated work, not a return", () => {
  it("appears once, in do-not-miss, never ranked by expectation per hour", () => {
    // Ranking it among the returns would bury the one call that has to happen before a missed
    // payment — after which no arrangement takes the delinquency back.
    const b = buildBrief(
      input({
        negotiation: [
          negotiationCase({ account: "h", institution: "Beta", ask: "hardship-plan", annualValueIfWon: usd(300), urgency: "CALL BEFORE A PAYMENT IS MISSED" }),
          negotiationCase(),
        ],
      }),
    );
    expect(b.doNotMiss.filter((a) => a.title.includes("hardship"))).toHaveLength(1);
    expect(b.bestReturn.some((a) => a.title.includes("hardship"))).toBe(false);
    expect(b.doNotMiss[0].why).toContain("BEFORE A PAYMENT IS MISSED");
  });
});

describe("blocked work is listed with what unblocks it", () => {
  it("keeps an ineligible opportunity and names the requirement", () => {
    const b = buildBrief(
      input({
        opportunities: [
          {
